import type { AccountIds } from "@/services/campaigns";
import { msadsFetch } from "@/services/msads-api";
import { hashBatch } from "@/services/pii";
import {
  assertBatchLimit,
  BATCH_LIMITS,
  type BatchResult,
  mapBatchResult,
} from "@/utils/batch";
import { MsAdsError } from "@/utils/errors";

/**
 * Audiences, including customer-match list upload.
 *
 * Not every audience type is writable. Several are generated by Microsoft or by
 * a DMP and can only be *associated* with a campaign, never created — which the
 * API expresses as a runtime error rather than a schema difference.
 */

/** Audience types this API lets you create. */
export const CREATABLE_AUDIENCE_TYPES = [
  "RemarketingList",
  "CustomerList",
  "ProductAudience",
  "CombinedList",
  "ImpressionBasedRemarketingList",
] as const;

/** Audience types that the update operation accepts. */
export const UPDATEABLE_AUDIENCE_TYPES = ["RemarketingList", "CustomAudience"] as const;

/** Audience types that exist but can only be read and associated. */
const READ_ONLY_AUDIENCE_TYPES: Record<string, string> = {
  InMarketAudience:
    "InMarketAudience is curated by Microsoft — it can be targeted but not created, updated, or deleted.",
  SimilarRemarketingList:
    "SimilarRemarketingList is generated automatically from a source remarketing list and is removed with it.",
  CustomAudience:
    "CustomAudience is created by a data-management platform. Only its Name and Description can be updated here.",
  CustomSegment: "CustomSegment cannot be created through the API.",
};

export function assertCreatableAudience(type: unknown): void {
  if (typeof type !== "string") return;
  const reason = READ_ONLY_AUDIENCE_TYPES[type];
  if (reason) throw new MsAdsError({ message: reason });

  if (!(CREATABLE_AUDIENCE_TYPES as readonly string[]).includes(type)) {
    throw new MsAdsError({
      message: `Unknown audience type "${type}". Creatable types: ${CREATABLE_AUDIENCE_TYPES.join(", ")}.`,
    });
  }
}

export async function getAudiencesByIds(
  ids: AccountIds,
  audienceIds?: string[],
  type?: string,
): Promise<Record<string, unknown>[]> {
  const res = await msadsFetch<{ Audiences?: Record<string, unknown>[] }>(
    "CampaignManagement",
    "Audiences/QueryByIds",
    {
      body: {
        AudienceIds: audienceIds ?? null,
        ...(type ? { Type: type } : {}),
      },
      ...ids,
      retry: "safe",
    },
  );
  return res.Audiences ?? [];
}

export async function addAudiences(
  ids: AccountIds,
  audiences: Record<string, unknown>[],
): Promise<BatchResult> {
  assertBatchLimit(audiences, BATCH_LIMITS.audiences, "audiences");
  for (const a of audiences) assertCreatableAudience(a.Type);

  const res = await msadsFetch<Record<string, unknown>>(
    "CampaignManagement",
    "Audiences",
    { method: "POST", body: { Audiences: audiences }, ...ids },
  );
  return mapBatchResult(
    res,
    "AudienceIds",
    audiences.map((a) => String(a.Name ?? "")),
    audiences.length,
  );
}

export async function updateAudiences(
  ids: AccountIds,
  audiences: Record<string, unknown>[],
): Promise<BatchResult> {
  assertBatchLimit(audiences, BATCH_LIMITS.audiences, "audiences");
  for (const audience of audiences) {
    if (
      typeof audience.Type !== "string" ||
      !(UPDATEABLE_AUDIENCE_TYPES as readonly string[]).includes(audience.Type)
    ) {
      throw new MsAdsError({
        message:
          `Audience ${String(audience.Id ?? "update")} needs Type set to an updateable family: ` +
          UPDATEABLE_AUDIENCE_TYPES.join(", ") +
          ".",
      });
    }
    if (audience.Type === "CustomAudience") {
      const unsupported = Object.keys(audience).filter(
        (field) => !["Id", "Type", "Name", "Description"].includes(field),
      );
      if (unsupported.length > 0) {
        throw new MsAdsError({
          message: `CustomAudience updates only support Name and Description; remove ${unsupported.join(", ")}.`,
        });
      }
    }
  }
  const res = await msadsFetch<Record<string, unknown>>(
    "CampaignManagement",
    "Audiences",
    { method: "PUT", body: { Audiences: audiences }, ...ids },
  );
  return mapBatchResult(
    { AudienceIds: audiences.map((a) => a.Id ?? null), ...res },
    "AudienceIds",
    audiences.map((a) => String(a.Name ?? a.Id ?? "")),
    audiences.length,
  );
}

export async function deleteAudiences(
  ids: AccountIds,
  audienceIds: string[],
): Promise<BatchResult> {
  assertBatchLimit(audienceIds, BATCH_LIMITS.audiences, "audiences");
  const res = await msadsFetch<Record<string, unknown>>(
    "CampaignManagement",
    "Audiences",
    { method: "DELETE", body: { AudienceIds: audienceIds }, ...ids },
  );
  return mapBatchResult(
    { AudienceIds: audienceIds, ...res },
    "AudienceIds",
    audienceIds,
    audienceIds.length,
  );
}

/** Max identifiers per customer-list call. */
export const CUSTOMER_LIST_MAX_ITEMS = 1000;

export type CustomerListAction = "Add" | "Remove" | "Replace";

export interface CustomerListUpload {
  audienceId: string;
  action: CustomerListAction;
  /** Plaintext or already-hashed emails; hashed here before sending. */
  emails: string[];
}

export interface CustomerListResult {
  audienceId: string;
  action: CustomerListAction;
  submitted: number;
  preHashed: number;
  rejected: Array<{ index: number; reason: string }>;
  message: string;
}

/**
 * Upload members to a customer-match list.
 *
 * Uses `ApplyCustomerListUserData`, not `ApplyCustomerListItems` — the latter
 * is deprecated for internal and external users alike.
 *
 * Only the `Email` subtype works today. `CRM` and `Phone` appear in the enum
 * but Microsoft documents them as not currently supported, so a phone-based
 * upload would silently match nothing.
 *
 * `AcceptCustomerMatchTerm` is sent explicitly as `true`. Omitting it falls
 * back to whether someone accepted the terms in the web UI, which for a
 * headless server means an unpredictable error 8003.
 */
export async function applyCustomerList(
  ids: AccountIds,
  upload: CustomerListUpload,
): Promise<CustomerListResult> {
  if (upload.emails.length === 0) {
    throw new MsAdsError({ message: "No email addresses supplied." });
  }
  if (upload.emails.length > CUSTOMER_LIST_MAX_ITEMS) {
    throw new MsAdsError({
      message:
        `Too many entries: ${upload.emails.length}. The API accepts at most ${CUSTOMER_LIST_MAX_ITEMS} per call. ` +
        "Split the list and send Add batches after an initial Replace.",
    });
  }

  const hashed = hashBatch(upload.emails, "email");
  if (hashed.hashes.length === 0) {
    throw new MsAdsError({
      message: `None of the ${upload.emails.length} entries could be normalized. First reason: ${hashed.rejected[0]?.reason}`,
    });
  }

  await msadsFetch("CampaignManagement", "CustomerListUserData/Apply", {
    body: {
      CustomerListUserData: {
        AcceptCustomerMatchTerm: true,
        ActionType: upload.action,
        AudienceId: upload.audienceId,
        CustomerListItemSubType: "Email",
        CustomerListItems: hashed.hashes,
      },
    },
    ...ids,
  });

  return {
    audienceId: upload.audienceId,
    action: upload.action,
    submitted: hashed.hashes.length,
    preHashed: hashed.preHashed,
    rejected: hashed.rejected,
    message:
      "Accepted. Microsoft takes roughly 48 hours to complete matching, and an audience needs about 1,000 matched users before it can be targeted.",
  };
}
